result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "server.js", "content": "'use strict';
const express = require('express');

/**
 * Shared helpers.
 */
function makeDb(betterSqlite3, path = ':memory:') {
  const db = betterSqlite3(path);
  db.pragma('journal_mode = WAL');
  db.exec(`
    CREATE TABLE IF NOT EXISTS settings (
      user_id TEXT PRIMARY KEY,
      doc     TEXT NOT NULL DEFAULT '{}'
    );
  `);
  return db;
}

function seedSettings(db, userId, doc = {}) {
  db.prepare(
    'INSERT INTO settings (user_id, doc) VALUES (?, ?) ON CONFLICT(user_id) DO UPDATE SET doc=excluded.doc'
  ).run(userId, JSON.stringify(doc));
}

function readDoc(db, userId) {
  const row = db.prepare('SELECT doc FROM settings WHERE user_id=?').get(userId);
  return row ? JSON.parse(row.doc) : null;
}

// Simulated slow side-effect: the async gap that opens the race window.
async function audit(doc) {
  await new Promise((resolve) => setImmediate(resolve));
  return doc;
}

/**
 * BUGGY handler — reproduced verbatim from the report.
 * Read-modify-write across an await => classic lost update:
 * two concurrent PUTs each read the same base document, merge their own
 * key, and the second write clobbers the first writer's key.
 *
 * @param {import('better-sqlite3').Database} db
 */
function buggyPutHandler(db) {
  return async function putHandler(req, res) {
    const row = db.prepare('SELECT doc FROM settings WHERE user_id=?').get(req.params.userId);
    const doc = JSON.parse(row.doc);
    Object.assign(doc, req.body);
    await audit(doc); // async gap
    db.prepare('UPDATE settings SET doc=? WHERE user_id=?').run(JSON.stringify(doc), req.params.userId);
    res.json(doc);
  };
}

/**
 * FIXED handler.
 * The entire read-merge-write collapses into ONE atomic SQLite statement:
 * json_patch merges the incoming partial object into the stored JSON
 * inside the UPDATE itself. SQLite serializes writers, so no interleaving
 * is possible — there is no stale in-memory copy to lose.
 *
 * @param {import('better-sqlite3').Database} db
 */
function fixedPutHandler(db) {
  return function putHandler(req, res) {
    const patch = JSON.stringify(req.body ?? {});
    const info = db
      .prepare(
        `UPDATE settings
            SET doc = json_patch(doc, json(?))
          WHERE user_id = ?`
      )
      .run(patch, req.params.userId);
    if (info.changes === 0) return res.status(404).json({ error: 'user not found' });
    res.json(readDoc(db, req.params.userId));
  };
}

/**
 * Alternative fix (equivalent semantics): explicit transaction wrapping the
 * synchronous read-merge-write. better-sqlite3 transactions are synchronous,
 * so the event loop cannot interleave another request mid-transaction.
 *
 * @param {import('better-sqlite3').Database} db
 */
function transactionalPutHandler(db) {
  const merge = db.transaction((userId, patch) => {
    const row = db.prepare('SELECT doc FROM settings WHERE user_id=?').get(userId);
    if (!row) return null;
    const doc = JSON.parse(row.doc);
    Object.assign(doc, patch);
    db.prepare('UPDATE settings SET doc=? WHERE user_id=?').run(JSON.stringify(doc), userId);
    return doc;
  });
  return function putHandler(req, res) {
    const doc = merge(req.params.userId, req.body ?? {});
    if (!doc) return res.status(404).json({ error: 'user not found' });
    res.json(doc);
  };
}

function createApp(db, handler = fixedPutHandler(db)) {
  const app = express();
  app.use(express.json());
  app.put('/settings/:userId', handler);
  return app;
}

module.exports = { makeDb, seedSettings, readDoc, audit, buggyPutHandler, fixedPutHandler, transactionalPutHandler, createApp };

// Allow manual poking: node server.js
if (require.main === module) {
  const Database = require('better-sqlite3');
  const db = makeDb(Database, process.env.DB_PATH || ':memory:');
  seedSettings(db, 'u1', { theme: 'light', lang: 'en' });
  createApp(db).listen(3000, () => console.log('listening on :3000'));
}
"})
