result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "lost-update.test.js", "content": "'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const http = require('node:http');

const {
  makeDb,
  seedSettings,
  readDoc,
  buggyPutHandler,
  fixedPutHandler,
  transactionalPutHandler,
  createApp,
} = require('./server.js');

function listen(app) {
  return new Promise((resolve) => {
    const server = app.listen(0, '127.0.0.1', () => resolve(server));
  });
}

function put(server, userId, body) {
  const { port } = server.address();
  return fetch(`http://127.0.0.1:${port}/settings/${userId}`, {
    method: 'PUT',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  }).then((r) => r.json());
}

function freshDb(userId, initial) {
  const Database = require('better-sqlite3');
  const db = makeDb(Database);
  seedSettings(db, userId, initial);
  return db;
}

test('BUGGY handler: two concurrent PUTs on different keys lose one key', async () => {
  const USER = 'u1';
  const db = freshDb(USER, { theme: 'light', lang: 'en' });
  const server = await listen(createApp(db, buggyPutHandler(db)));

  // Fire simultaneously: {theme} writer and {lang} writer race.
  const [a, b] = await Promise.all([
    put(server, USER, { theme: 'dark' }),
    put(server, USER, { lang: 'fr' }),
  ]);

  const final = readDoc(db, USER);
  console.log('buggy final doc:', final);
  console.log('  responses:', a, b);

  // PROOF of the lost update: one of the keys vanished even though both
  // writers succeeded (HTTP 200 with their own key merged in).
  const lostKeys = [];
  if (!('theme' in final)) lostKeys.push('theme');
  if (!('lang' in final)) lostKeys.push('lang');
  assert.ok(
    lostKeys.length > 0,
    `expected a lost key but both survived: ${JSON.stringify(final)}`
  );
  // The last writer's response contains BOTH its own change and stale base,
  // i.e. it silently overwrote the sibling update.
  assert.equal(Object.keys(final).length, 1);

  server.close();
});

test('FIXED (json_patch): concurrent PUTs on different keys keep both keys', async () => {
  const USER = 'u1';
  const db = freshDb(USER, { theme: 'light', lang: 'en' });
  const server = await listen(createApp(db, fixedPutHandler(db)));

  await Promise.all([
    put(server, USER, { theme: 'dark' }),
    put(server, USER, { lang: 'fr' }),
  ]);

  const final = readDoc(db, USER);
  assert.deepEqual(final, { theme: 'dark', lang: 'fr' });
  server.close();
});

test('FIXED (transaction): concurrent PUTs on different keys keep both keys', async () => {
  const USER = 'u1';
  const db = freshDb(USER, { theme: 'light', lang: 'en' });
  const server = await listen(createApp(db, transactionalPutHandler(db)));

  await Promise.all([
    put(server, USER, { theme: 'dark' }),
    put(server, USER, { lang: 'fr' }),
  ]);

  assert.deepEqual(readDoc(db, USER), { theme: 'dark', lang: 'fr' });
  server.close();
});

test('REGRESSION: 20 racing mixed updates — every key survives under json_patch', async () => {
  const USER = 'race-user';
  const db = freshDb(USER, {});
  const server = await listen(createApp(db, fixedPutHandler(db)));

  // 20 updates across DIFFERENT keys, all fired concurrently.
  const patches = [];
  for (let i = 0; i < 20; i++) patches.push({ [`key${i}`]: `value-${i}` });
  const results = await Promise.all(patches.map((p) => put(server, USER, p)));

  // Every request reported success.
  for (const r of results) assert.ok(r && !r.error, `unexpected response: ${JSON.stringify(r)}`);

  const final = readDoc(db, USER);
  // No lost updates: all 20 distinct keys must be present with the written value.
  for (let i = 0; i < 20; i++) {
    assert.equal(
      final[`key${i}`],
      `value-${i}`,
      `lost update detected: key${i} missing/overwritten in ${JSON.stringify(final)}`
    );
  }
  assert.equal(Object.keys(final).length, 20);
  server.close();
});

test('REGRESSION: 20 racing mixed updates also safe under the transactional fix', async () => {
  const USER = 'race-user-tx';
  const db = freshDb(USER, {});
  const server = await listen(createApp(db, transactionalPutHandler(db)));

  const patches = Array.from({ length: 20 }, (_, i) => ({ [`k${i}`]: i }));
  await Promise.all(patches.map((p) => put(server, USER, p)));

  const final = readDoc(db, USER);
  for (let i = 0; i < 20; i++) assert.equal(final[`k${i}`], i);
  server.close();
});
"})
