 * Send a PUT over a raw socket. Used to guarantee two requests hit the
 * server in the same event-loop turn (undici's pool may serialize them).
 */
function rawSocketPut(server, userId, body) {
  const payload = JSON.stringify(body);
  return new Promise((resolve, reject) => {
    const chunks = [];
    const sock = net.connect(server.address().port, '127.0.0.1', () => {
      sock.write(
        `PUT /settings/${userId} HTTP/1.1\r\n` +
          `Host: localhost\r\n` +
          `Content-Type: application/json\r\n` +
          `Content-Length: ${Buffer.byteLength(payload)}\r\n` +
          `Connection: close\r\n\r\n` +
          payload
      );
    });
    sock.on('data', (c) => chunks.push(c));
    sock.on('end', () => {
      const raw = Buffer.concat(chunks).toString();
      const jsonPart = raw.slice(raw.indexOf('\r\n\r\n') + 4);
      try {
        resolve(JSON.parse(jsonPart));
      } catch (e) {
        reject(new Error(`unparseable response: ${raw}`));
      }
    });
    sock.on('error', reject);
  });
}

/**
 * Race two PUTs so BOTH arrive before either handler passes its SELECT:
 * open both TCP connections first, only then write both payloads in the
 * same tick.
 */
function raceTwoPuts(server, userId, bodyA, bodyB) {
  const connect = () =>
    new Promise((resolve, reject) => {
      const chunks = [];
      const sock = net.connect(server.address().port, '127.0.0.1', () => resolve({ sock, chunks }));
      sock.on('data', (c) => chunks.push(c));
      sock.on('error', reject);
    });
  return Promise.all([connect(), connect()]).then(async ([a, b]) => {
    // Wait a macrotask so the server has accept()ed both connections,
    // then blast both requests back-to-back with zero intervening I/O.
    await new Promise((r) => setTimeout(r, 25));
    const send = ({ sock, chunks }, userId_, body) => {
      const payload = JSON.stringify(body);
      sock.end(
        `PUT /settings/${userId_} HTTP/1.1\r\n` +
          `Host: localhost\r\n` +
          `Content-Type: application/json\r\n` +
          `Content-Length: ${Buffer.byteLength(payload)}\r\n` +
          `Connection: close\r\n\r\n` +
          payload
      );
      return new Promise((resolve) =>
        sock.on('end', () => {
          const raw = Buffer.concat(chunks).toString();
          resolve(JSON.parse(raw.slice(raw.indexOf('\r\n\r\n') + 4)));
        })
      );
    };
    return Promise.all([send(a, userId, bodyA), send(b, userId, bodyB)]);
  });
}

